","/* ═══════════════════════════════════════════════════════════════════════
 Industrial Supply Co. — Customer Portal Stylesheet (Enhanced)
 Includes shared design-system tokens + portal-specific layout.
 White/Light Enterprise Theme — Professional Industrial Appearance
 ═══════════════════════════════════════════════════════════════════════ */

:root {
 /* ── Brand ────────────────────────────────────── */
 --ids-brand-navy: #0f2438;
 --ids-brand-navy-light: #1a3a5c;
 --ids-brand-accent: #2563eb;
 --ids-brand-accent-hover:#1d4ed8;

 /* ── Backgrounds ──────────────────────────────── */
 --ids-bg-page: #f1f5f9;
 --ids-bg-card: #ffffff;
 --ids-bg-surface: #f8fafc;
 --ids-bg-hover: #f1f5f9;
 --ids-bg-active: #e2e8f0;

 /* ── Text ─────────────────────────────────────── */
 --ids-text-primary: #0f172a;
 --ids-text-secondary: #475569;
 --ids-text-tertiary: #94a3b8;
 --ids-text-inverse: #ffffff;
 --ids-text-link: #2563eb;

 /* ── Borders ──────────────────────────────────── */
 --ids-border: #e2e8f0;
 --ids-border-light: #f1f5f9;
 --ids-border-focus: #2563eb;

 /* ── Status / Semantic ────────────────────────── */
 --ids-success: #16a34a;
 --ids-success-bg: rgba(22,163,74,.08);
 --ids-warning: #d97706;
 --ids-warning-bg: rgba(217,119,6,.08);
 --ids-error: #dc2626;
 --ids-error-bg: rgba(220,38,38,.06);
 --ids-info: #0284c7;
 --ids-info-bg: rgba(2,132,199,.08);

 /* ── Spacing ──────────────────────────────────── */
 --ids-sp-1: 4px; --ids-sp-2: 8px; --ids-sp-3: 12px;
 --ids-sp-4: 16px; --ids-sp-5: 20px; --ids-sp-6: 24px;
 --ids-sp-8: 32px; --ids-sp-10: 40px; --ids-sp-12: 48px;

 /* ── Radius ───────────────────────────────────── */
 --ids-radius-sm: 8px;
 --ids-radius-md: 12px;
 --ids-radius-lg: 16px;
 --ids-radius-full: 9999px;

 /* ── Shadows ──────────────────────────────────── */
 --ids-shadow-sm: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
 --ids-shadow-md: 0 4px 12px rgba(0,0,0,.08), 0 2px 4px rgba(0,0,0,.04);
 --ids-shadow-lg: 0 8px 24px rgba(0,0,0,.10), 0 4px 8px rgba(0,0,0,.06);
 --ids-shadow-glow: 0 0 0 3px rgba(37,99,235,.12);

 /* ── Typography ───────────────────────────────── */
 --ids-font: "Source Sans Pro", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 --ids-font-mono: "SF Mono", "Fira Code", "Fira Mono", Menlo, monospace;
 --ids-text-xs: 11px;
 --ids-text-sm: 13px;
 --ids-text-md: 14px;
 --ids-text-lg: 16px;
 --ids-text-xl: 20px;
 --ids-text-2xl: 24px;
 --ids-text-3xl: 28px;

 /* ── Transitions ──────────────────────────────── */
 --ids-transition: all .2s cubic-bezier(.4,0,.2,1);
}

/* ── Global Reset ───────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; }
body { font-family: var(--ids-font); color: var(--ids-text-primary); background: var(--ids-bg-page); }

/* ── Scrollbar ──────────────────────────────────── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }
::-webkit-scrollbar-track { background: transparent; }

/* ═══════════════════════════════════════════════════
 SHARED UTILITY CLASSES (Enhanced Design System)
 ═══════════════════════════════════════════════════ */

.ids-card {
 background: var(--ids-bg-card); border-radius: var(--ids-radius-md);
 border: 1px solid var(--ids-border); padding: var(--ids-sp-6);
 box-shadow: var(--ids-shadow-md); transition: var(--ids-transition);
}
.ids-card:hover {
 box-shadow: var(--ids-shadow-lg); transform: translateY(-1px);
}
.ids-card-title {
 margin: 0 0 var(--ids-sp-4) 0; font-size: 16px; font-weight: 700;
 color: var(--ids-text-primary); letter-spacing: .01em;
}

.ids-badge {
 display: inline-flex; align-items: center; justify-content: center;
 padding: 3px 12px; border-radius: var(--ids-radius-full);
 font-size: var(--ids-text-xs); font-weight: 700;
 text-transform: capitalize; letter-spacing: .04em; white-space: nowrap;
}
.ids-badge-info { background: var(--ids-info-bg); color: var(--ids-info); }
.ids-badge-success { background: var(--ids-success-bg); color: var(--ids-success); }
.ids-badge-warning { background: var(--ids-warning-bg); color: var(--ids-warning); }
.ids-badge-error { background: var(--ids-error-bg); color: var(--ids-error); }

.ids-btn {
 display: inline-flex; align-items: center; justify-content: center; gap: 8px;
 padding: 9px 18px; border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-sm); font-weight: 600; font-family: var(--ids-font);
 cursor: pointer; border: 1px solid transparent;
 transition: var(--ids-transition);
}
.ids-btn:focus-visible { outline: 2px solid var(--ids-border-focus); outline-offset: 2px; }
.ids-btn:active { transform: scale(.97); }
.ids-btn-primary {
 background: var(--ids-brand-navy); color: var(--ids-text-inverse); border-color: var(--ids-brand-navy);
}
.ids-btn-primary:hover { background: var(--ids-brand-navy-light); box-shadow: var(--ids-shadow-sm); }
.ids-btn-accent {
 background: var(--ids-brand-accent); color: var(--ids-text-inverse); border-color: var(--ids-brand-accent);
}
.ids-btn-accent:hover { background: var(--ids-brand-accent-hover); box-shadow: var(--ids-shadow-sm); }
.ids-btn-ghost {
 background: transparent; color: var(--ids-brand-accent); border-color: var(--ids-border);
}
.ids-btn-ghost:hover { background: var(--ids-bg-hover); box-shadow: var(--ids-shadow-sm); }
.ids-btn-danger { background: var(--ids-error); color: #fff; border-color: var(--ids-error); }
.ids-btn-danger:hover { box-shadow: var(--ids-shadow-sm); }
.ids-btn-link {
 background: none; border: none; color: var(--ids-text-link);
 padding: 0; font-size: 13px; font-weight: 600; cursor: pointer;
 font-family: var(--ids-font); transition: var(--ids-transition);
}
.ids-btn-link:hover { text-decoration: underline; }

.ids-table { width: 100%; border-collapse: collapse; }
.ids-table th {
 padding: 14px 16px; font-size: 12px; font-weight: 700;
 text-transform: uppercase; letter-spacing: .05em;
 color: var(--ids-text-tertiary); text-align: left;
 border-bottom: 2px solid var(--ids-border); background: var(--ids-bg-surface);
}
.ids-table td {
 padding: 14px 16px; font-size: var(--ids-text-sm); color: var(--ids-text-primary);
 border-bottom: 1px solid var(--ids-border-light); vertical-align: middle;
}
.ids-table tr:hover td { background: rgba(37,99,235,.03); }

.ids-kpi {
 background: var(--ids-bg-card); border-radius: var(--ids-radius-md);
 border: 1px solid var(--ids-border); border-top: 3px solid transparent;
 padding: 24px 20px; min-height: 120px;
 display: flex; flex-direction: column; align-items: center; gap: 8px;
 text-align: center; box-shadow: var(--ids-shadow-md);
 transition: var(--ids-transition);
}
.ids-kpi:hover {
 transform: translateY(-2px); box-shadow: var(--ids-shadow-lg);
}
.ids-kpi-value { font-size: var(--ids-text-3xl); font-weight: 700; line-height: 1.1; }
.ids-kpi-label {
 font-size: var(--ids-text-xs); font-weight: 600; color: var(--ids-text-tertiary);
 text-transform: uppercase; letter-spacing: .06em;
}

.ids-empty {
 display: flex; flex-direction: column; align-items: center; justify-content: center;
 padding: 56px 40px; gap: 14px; text-align: center;
 background: var(--ids-bg-surface); border-radius: var(--ids-radius-md);
}
.ids-empty-icon {
 width: 56px; height: 56px; border-radius: var(--ids-radius-lg);
 background: var(--ids-bg-surface); display: flex; align-items: center;
 justify-content: center; color: var(--ids-text-tertiary); font-size: 24px;
 border: 1px solid var(--ids-border);
}
.ids-empty-title { font-size: var(--ids-text-lg); font-weight: 600; color: var(--ids-text-primary); }
.ids-empty-desc { font-size: var(--ids-text-sm); color: var(--ids-text-tertiary); max-width: 380px; line-height: 1.5; }

@keyframes ids-spin { to { transform: rotate(360deg); } }
.ids-spinner {
 width: 28px; height: 28px;
 border: 3px solid var(--ids-border);
 border-top-color: var(--ids-brand-navy);
 border-radius: 50%;
 animation: ids-spin .8s linear infinite;
}

.ids-grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 18px; }
.ids-grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 18px; }
.ids-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }

/* ═══════════════════════════════════════════════════
 PORTAL LAYOUT — Header, Nav Tabs, Content
 ═══════════════════════════════════════════════════ */

.portal-shell {
 display: flex; flex-direction: column; height: 100vh; width: 100%;
 font-family: var(--ids-font); background: var(--ids-bg-page);
}

/* ── Header ─────────────────────────────────────── */
.portal-header {
 background: var(--ids-brand-navy); color: var(--ids-text-inverse);
 flex-shrink: 0; box-shadow: 0 2px 12px rgba(0,0,0,.18);
}
.portal-header-top {
 display: flex; align-items: center; justify-content: space-between;
 padding: 0 36px; height: 60px;
}
.portal-brand {
 font-size: 18px; font-weight: 700; letter-spacing: .01em;
 display: flex; align-items: center; gap: 12px;
}
.portal-brand-icon {
 width: 32px; height: 32px; border-radius: 8px;
 background: rgba(255,255,255,.15); display: flex;
 align-items: center; justify-content: center; font-size: 15px;
}
.portal-header-right {
 display: flex; align-items: center; gap: 20px;
}
.portal-customer-name {
 font-size: 13.5px; opacity: .85; font-weight: 500;
}
.portal-cart-btn {
 background: rgba(255,255,255,.12); border: none; color: #fff;
 padding: 7px 14px; border-radius: var(--ids-radius-sm);
 cursor: pointer; font-family: var(--ids-font); font-size: 13px;
 font-weight: 600; display: flex; align-items: center; gap: 6px;
 transition: var(--ids-transition);
 position: relative;
}
.portal-cart-btn:hover { background: rgba(255,255,255,.22); }
.portal-cart-badge {
 position: absolute; top: -6px; right: -6px;
 min-width: 18px; height: 18px; padding: 0 5px;
 border-radius: 9px; background: var(--ids-brand-accent);
 color: #fff; font-size: 10px; font-weight: 700;
 display: flex; align-items: center; justify-content: center;
}

/* ── Nav Tabs ───────────────────────────────────── */
.portal-nav {
 display: flex; align-items: center; gap: 2px;
 padding: 0 36px; background: rgba(0,0,0,.15);
 overflow-x: auto;
}
.portal-tab {
 padding: 12px 18px; font-size: 13.5px; font-weight: 500;
 color: rgba(255,255,255,.65); background: none; border: none;
 border-bottom: 3px solid transparent; cursor: pointer;
 white-space: nowrap; font-family: var(--ids-font);
 transition: var(--ids-transition);
}
.portal-tab:hover { color: rgba(255,255,255,.9); }
.portal-tab-active {
 color: #fff; font-weight: 600;
 border-bottom-color: var(--ids-brand-accent);
}

/* ── Content ────────────────────────────────────── */
.portal-content {
 flex: 1; overflow-y: auto; padding: 32px 36px;
}
.portal-section {
 max-width: 1200px; margin: 0 auto;
}

/* ═══════════════════════════════════════════════════
 PORTAL SECTIONS (Enhanced)
 ═══════════════════════════════════════════════════ */

/* ── Section Header ─────────────────────────────── */
.section-header {
 margin-bottom: 28px;
}
.section-title {
 margin: 0; font-size: var(--ids-text-2xl); font-weight: 700;
 color: var(--ids-brand-navy);
}
.section-subtitle {
 margin: 8px 0 0; font-size: var(--ids-text-md); color: var(--ids-text-secondary);
 line-height: 1.5;
}

/* ── Product Grid / Cards (Enhanced) ────────────── */
/* ── INDUSTRIAL CATALOG PRODUCT GRID ── */
.product-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
 gap: 20px;
 margin-top: 20px;
}

.product-card {
 background: #ffffff;
 border: 1px solid var(--ids-border, #e2e8f0);
 border-radius: 10px;
 overflow: hidden;
 box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
 transition: box-shadow 0.2s ease, transform 0.15s ease;
 display: flex;
 flex-direction: column;
}
.product-card:hover {
 box-shadow: 0 6px 20px rgba(15, 23, 42, 0.12);
 transform: translateY(-2px);
}

.product-card-header {
 background: linear-gradient(135deg, #0f2438 0%, #1e3a5f 100%);
 padding: 14px 18px;
 display: flex;
 justify-content: space-between;
 align-items: center;
}
.product-card-header .product-card-id {
 font-family: var(--ids-font-mono, 'SFMono-Regular', Consolas, monospace);
 font-size: 11.5px;
 color: #94a3b8;
 letter-spacing: 0.3px;
}
.product-card-header .product-card-category {
 font-size: 10.5px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 color: #38bdf8;
}

.product-card-body {
 padding: 18px;
 flex: 1;
 display: flex;
 flex-direction: column;
}
.product-card-name {
 font-size: 15px;
 font-weight: 700;
 color: #0f172a;
 margin-bottom: 8px;
 line-height: 1.35;
}
.product-card-desc {
 font-size: 13px;
 color: #64748b;
 line-height: 1.5;
 margin: 0 0 16px;
 flex: 1;
 display: -webkit-box;
 -webkit-line-clamp: 3;
 -webkit-box-orient: vertical;
 overflow: hidden;
}

.product-card-footer {
 padding: 14px 18px;
 border-top: 1px solid #f1f5f9;
 display: flex;
 justify-content: space-between;
 align-items: center;
 background: #f8fafc;
}
.product-price {
 font-size: 17px;
 font-weight: 700;
 color: #0f2438;
}
.product-uom {
 font-size: 12px;
 color: #94a3b8;
 margin-left: 3px;
}

/* ── INDUSTRIAL PRODUCT DETAIL ── */
.product-detail {
 display: grid;
 grid-template-columns: 1fr 360px;
 gap: 24px;
 align-items: start;
}

.pricing-card {
 background: #ffffff;
 border: 1px solid var(--ids-border, #e2e8f0);
 border-radius: 10px;
 padding: 24px;
 box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
 position: sticky;
 top: 80px;
}
.pricing-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 10px 0;
 border-bottom: 1px solid #f1f5f9;
}
.pricing-total {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 14px 0 0;
 margin-top: 10px;
 border-top: 2px solid #0f2438;
 font-size: 16px;
 font-weight: 700;
 color: #0f2438;
}

/* ── Cart (Enhanced) ────────────────────────────── */
.cart-item {
 display: flex; align-items: center; gap: 18px;
 padding: 18px 0; border-bottom: 1px solid var(--ids-border-light);
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: 15px; font-weight: 600; color: var(--ids-text-primary); }
.cart-item-meta { font-size: 12.5px; color: var(--ids-text-tertiary); margin-top: 3px; }
.cart-controls {
 display: flex; align-items: center; gap: 0;
 border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm); overflow: hidden;
}
.cart-qty-btn {
 width: 34px; height: 34px; border: none; background: var(--ids-bg-surface);
 cursor: pointer; font-size: 16px; font-weight: 600; color: var(--ids-text-primary);
 display: flex; align-items: center; justify-content: center;
 font-family: var(--ids-font); transition: var(--ids-transition);
}
.cart-qty-btn:hover { background: var(--ids-bg-hover); }
.cart-qty-display {
 width: 44px; text-align: center; font-size: 14px; font-weight: 600;
 font-family: var(--ids-font-mono); border-left: 1px solid var(--ids-border);
 border-right: 1px solid var(--ids-border); line-height: 34px;
}
.cart-item-price { font-size: 15px; font-weight: 700; color: var(--ids-brand-navy); width: 100px; text-align: right; }
.cart-remove {
 background: none; border: none; color: var(--ids-text-tertiary);
 cursor: pointer; font-size: 18px; padding: 4px; transition: var(--ids-transition);
}
.cart-remove:hover { color: var(--ids-error); }
.cart-footer {
 display: flex; justify-content: space-between; align-items: center;
 padding: 22px 0 0; margin-top: 10px; border-top: 2px solid var(--ids-border);
}
.cart-total { font-size: 22px; font-weight: 700; color: var(--ids-brand-navy); }
.cart-actions { display: flex; gap: 12px; }

/* ── Order Review Form (Enhanced) ───────────────── */
.order-form { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 22px; }
.order-form-field { display: flex; flex-direction: column; gap: 6px; }
.order-form-field.full { grid-column: 1 / -1; }
.order-form-label {
 font-size: var(--ids-text-xs); font-weight: 700; color: var(--ids-text-tertiary);
 text-transform: uppercase; letter-spacing: .04em;
}
.order-form-input {
 padding: 11px 16px; border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-md); font-family: var(--ids-font); color: var(--ids-text-primary);
 background: var(--ids-bg-card); transition: var(--ids-transition);
}
.order-form-input:focus { outline: none; border-color: var(--ids-border-focus); box-shadow: var(--ids-shadow-glow); }
textarea.order-form-input { min-height: 80px; resize: vertical; }

/* ── Filter Pills (Enhanced) ────────────────────── */
.filter-pills { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 22px; }
.filter-pill {
 padding: 7px 16px; border-radius: var(--ids-radius-full);
 font-size: var(--ids-text-xs); font-weight: 600; cursor: pointer;
 border: 1px solid var(--ids-border); background: var(--ids-bg-card);
 color: var(--ids-text-secondary); font-family: var(--ids-font);
 transition: var(--ids-transition);
}
.filter-pill:hover { background: var(--ids-bg-hover); border-color: var(--ids-brand-accent); color: var(--ids-brand-accent); }
.filter-pill-active {
 background: var(--ids-brand-accent); color: #fff;
 border-color: var(--ids-brand-accent);
}

/* ── Status Badges (Enhanced) ───────────────────── */
.status-badge {
 display: inline-flex; align-items: center; padding: 3px 12px;
 border-radius: var(--ids-radius-full); font-size: var(--ids-text-xs);
 font-weight: 700; text-transform: capitalize; letter-spacing: .03em;
}
.status-draft { background: #f1f5f9; color: #64748b; }
.status-submitted { background: var(--ids-info-bg); color: var(--ids-info); }
.status-approved { background: var(--ids-success-bg); color: var(--ids-success); }
.status-in_production{ background: var(--ids-warning-bg); color: var(--ids-warning); }
.status-completed { background: rgba(22,163,74,.12); color: #15803d; }
.status-cancelled { background: var(--ids-error-bg); color: var(--ids-error); }

/* ── Delivery (Enhanced) ────────────────────────── */
.delivery-list { display: flex; flex-direction: column; gap: 14px; }
.delivery-card {
 background: var(--ids-bg-card); border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-md); padding: 22px 26px;
 display: flex; align-items: center; justify-content: space-between;
 box-shadow: var(--ids-shadow-md); transition: var(--ids-transition);
}
.delivery-card:hover { box-shadow: var(--ids-shadow-lg); transform: translateY(-1px); }
.countdown { font-size: 15px; font-weight: 700; }
.countdown-ok { color: var(--ids-success); }
.countdown-soon { color: var(--ids-warning); }
.countdown-overdue { color: var(--ids-error); }

/* ── Profile (Enhanced) ─────────────────────────── */
.profile-grid {
 display: grid; grid-template-columns: 1fr 1fr; gap: 18px;
}
.profile-field {
 padding: 16px 20px; border-radius: var(--ids-radius-sm);
 background: var(--ids-bg-surface); border: 1px solid var(--ids-border-light);
 transition: var(--ids-transition);
}
.profile-field:hover { border-color: var(--ids-border); box-shadow: var(--ids-shadow-sm); }
.profile-label {
