}
.profile-value { font-size: var(--ids-text-md); font-weight: 500; color: var(--ids-text-primary); }

/* ── Surveys (Enhanced) ─────────────────────────── */
.rating-stars { display: flex; gap: 8px; margin-bottom: 18px; }
.star-btn {
