}

/* ── Search (Enhanced) ──────────────────────────── */
.search-bar {
 display: flex; align-items: center; gap: 12px;
 margin-bottom: 22px; position: relative;
}
.search-input {
 width: 100%; max-width: 420px; padding: 11px 16px 11px 40px;
 border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-md); font-family: var(--ids-font);
 color: var(--ids-text-primary); background: var(--ids-bg-card);
 transition: var(--ids-transition);
}
.search-input:focus { outline: none; border-color: var(--ids-border-focus); box-shadow: var(--ids-shadow-glow); }
.search-icon {
 position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
 color: var(--ids-text-tertiary); pointer-events: none; font-size: 14px;
}

/* ── Qty Input (Product Detail) ─────────────────── */
.qty-input {
 width: 80px;
 padding: 6px 10px;
 border: 1px solid #cbd5e1;
 border-radius: 6px;
 font-size: 14px;
 font-weight: 600;
 text-align: center;
 outline: none;
 transition: border-color 0.2s;
}
.qty-input:focus {
 border-color: #1e40af;
 box-shadow: 0 0 0 3px rgba(30, 64, 175, 0.12);
}

/* ── Success State (Enhanced) ───────────────────── */
.success-state {
 display: flex; flex-direction: column; align-items: center;
 padding: 64px 36px; text-align: center; gap: 18px;
}
.success-icon {
 width: 72px; height: 72px; border-radius: 50%;
 background: var(--ids-success-bg); color: var(--ids-success);
 display: flex; align-items: center; justify-content: center;
 font-size: 36px;
}
.success-title { font-size: var(--ids-text-xl); font-weight: 700; color: var(--ids-text-primary); }
.success-desc { font-size: var(--ids-text-md); color: var(--ids-text-secondary); max-width: 420px; line-height: 1.5; }

/* ── Best Sellers Bar ───────────────────────────── */
.bestseller-bar {
 display: flex; align-items: flex-end; gap: 2px; height: 100%;
 min-height: 24px;
}
.bestseller-segment {
 flex: 1; border-radius: 4px 4px 0 0; background: var(--ids-brand-accent);
 min-width: 0; transition: height .3s;
}

