 <div className="ids-empty-icon">🔒</div>
 <div className="ids-empty-title">Customer Account Not Linked</div>
 <div className="ids-empty-desc">{message || `No customer account is linked to ${email || "your email"}. Contact your account administrator.`}</div>
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ DASHBOARD ═══════════════════ */
function Dashboard({ orders, orderItems, products, navigate }: {
 orders: Rec[]; orderItems: Rec[]; products: Rec[]; navigate: (v: string, id?: string) => void;
}) {
 const total = orders.length;
 const active = orders.filter(o => {
 const s = val(o.status).toLowerCase();
 return s !== "completed" && s !== "cancelled";
 });
 const inProd = orders.filter(o => val(o.status).toLowerCase() === "in_production" || dv(o.status).toLowerCase() === "in production");
 const delivered = orders.filter(o => val(o.status).toLowerCase() === "completed" || val(o.status).toLowerCase() === "delivered");

 /* Next Delivery */
 const now = new Date();
 now.setHours(0, 0, 0, 0);
 let nextDelivery: Rec | null = null;
 let nextDays = Infinity;
 for (const o of active) {
 const dd = val(o.requested_delivery_date);
 if (!dd) continue;
 const d = daysUntil(dd);
 if (d >= 0 && d < nextDays) { nextDays = d; nextDelivery = o; }
 }

 /* Best Selling Products */
 const cancelledOrderIds = new Set(
 orders.filter(o => val(o.status).toLowerCase() === "cancelled").map(o => val(o.sys_id))
 );
 const productQty: Record<string, { name: string; qty: number }> = {};
 for (const item of orderItems) {
 const orderId = val(item.customer_order);
 if (cancelledOrderIds.has(orderId)) continue;
 const pName = dv(item.material_product) || "Unknown";
 const qty = parseInt(dv(item.quantity_ordered) || "0", 10) || 0;
 if (!productQty[pName]) productQty[pName] = { name: pName, qty: 0 };
 productQty[pName].qty += qty;
 }
 const bestSellers = Object.values(productQty).sort((a, b) => b.qty - a.qty).slice(0, 5);
 const maxQty = bestSellers.length > 0 ? bestSellers[0].qty : 1;

 return (
 <div className="portal-section">
 <SectionHeader title="Dashboard" sub="Overview of your orders and activity" />

 {/* KPI Strip */}
 <div className="ids-grid-4" style={{ marginBottom: 20 }}>
 <KpiCard value={total} label="Total Orders" color="var(--ids-brand-navy)" border="var(--ids-brand-navy)" />
 <KpiCard value={active.length} label="Active Orders" color="var(--ids-info)" border="var(--ids-info)" />
 <KpiCard value={inProd.length} label="In Production" color="var(--ids-warning)" border="var(--ids-warning)" />
 <KpiCard value={delivered.length} label="Delivered / Completed" color="var(--ids-success)" border="var(--ids-success)" />
 </div>

 {/* Current Orders + Next Delivery */}
 <div className="ids-grid-2" style={{ marginBottom: 20 }}>
 <div className="ids-card">
 <h3 className="ids-card-title">Current Orders</h3>
 {active.length === 0 ? (
 <EmptyState icon="📦" title="No active orders" desc="Place an order from the catalog to get started." />
 ) : (
 <div>
 {active.slice(0, 3).map((o, i) => (
 <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: i < 2 ? "1px solid var(--ids-border-light)" : "none" }}>
 <div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-link)", cursor: "pointer" }}
 onClick={() => navigate("order", val(o.sys_id))}>{dv(o.number)}</div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>{fmtDate(dv(o.order_date))}</div>
 </div>
 <StatusBadge status={val(o.status)} />
 </div>
 ))}
 {active.length > 3 && (
 <button className="ids-btn-link" style={{ marginTop: 12 }} onClick={() => navigate("orders")}>
 View all {active.length} active orders →
 </button>
 )}
 </div>
 )}
 </div>

 <div className="ids-card">
 <h3 className="ids-card-title">Next Delivery</h3>
 {nextDelivery ? (
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "20px 0", gap: 8 }}>
 <div style={{ fontSize: 40, fontWeight: 700, color: "var(--ids-brand-navy)" }}>
 {nextDays === 0 ? "Today" : `${nextDays}d`}
 </div>
 <div style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>
 {nextDays === 0 ? "Delivery expected today" : `${nextDays} day${nextDays !== 1 ? "s" : ""} until delivery`}
 </div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-link)", cursor: "pointer", marginTop: 4 }}
 onClick={() => navigate("order", val(nextDelivery!.sys_id))}>
 {dv(nextDelivery.number)}
 </div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>
 Delivery: {fmtDate(dv(nextDelivery.requested_delivery_date))}
 </div>
 </div>
 ) : (
 <EmptyState icon="🚚" title="No upcoming deliveries" desc="Active orders with delivery dates will appear here." />
 )}
 </div>
 </div>

 {/* Best Selling Products */}
 <div className="ids-card">
 <h3 className="ids-card-title">Best Selling Products</h3>
 {bestSellers.length === 0 ? (
 <EmptyState icon="📊" title="No order data yet" desc="Product rankings will appear once orders are placed." />
 ) : (
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {bestSellers.map((p, i) => (
 <div key={i} style={{ display: "flex", alignItems: "center", gap: 14 }}>
 <span style={{ width: 22, fontSize: 13, fontWeight: 700, color: "var(--ids-text-tertiary)", textAlign: "right" }}>#{i + 1}</span>
 <div style={{ flex: 1 }}>
 <div style={{ fontSize: 13, fontWeight: 600 }}>{p.name}</div>
 <div style={{ height: 6, borderRadius: 3, background: "var(--ids-bg-surface)", marginTop: 4, overflow: "hidden" }}>
 <div style={{ height: "100%", borderRadius: 3, background: "var(--ids-brand-accent)", width: `${(p.qty / maxQty) * 100}%`, transition: "width .4s" }} />
 </div>
 </div>
 <span style={{ fontSize: 14, fontWeight: 700, fontFamily: "var(--ids-font-mono)", color: "var(--ids-brand-navy)", minWidth: 50, textAlign: "right" }}>{p.qty}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ CATALOG ═══════════════════ */
function Catalog({ products, navigate }: { products: Rec[]; navigate: (v: string, id?: string) => void }) {
 const [search, setSearch] = useState("");
 const filtered = products.filter(p => {
 const name = dv(p.material_name).toLowerCase();
 return name.includes(search.toLowerCase());
 });

 return (
 <div className="portal-section">
 <SectionHeader title="Product Catalog" sub="Browse our finished industrial products and select what you need." />
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 4 }}>
 <div style={{ fontSize: 13, fontWeight: 600, color: "var(--ids-text-tertiary)" }}>
 {filtered.length} finished product{filtered.length !== 1 ? "s" : ""}
 </div>
 </div>
 <div className="search-bar">
 <span className="search-icon">🔍</span>
 <input className="search-input" placeholder="Search products by name…"
 value={search} onChange={e => setSearch(e.target.value)} />
 </div>
 {filtered.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🔍" title="No products found" desc={search ? "Try adjusting your search." : "No products are available."} />
 </div>
 ) : (
 <div className="product-grid">
 {filtered.map((p, i) => {
 const price = parsePrice(p.standard_cost);
 return (
 <div className="product-card" key={i}>
 <div className="product-card-header">
 <span className="product-card-id">{dv(p.material_product_id) || "—"}</span>
 <span className="product-card-category">{dv(p.category) || "General"}</span>
 </div>
 <div className="product-card-body">
 <div className="product-card-name">{dv(p.material_name)}</div>
 <p className="product-card-desc">{dv(p.description) || "No description available."}</p>
 </div>
 <div className="product-card-footer">
 <div>
 <span className="product-price">{price > 0 ? fmtCurrency(price) : "—"}</span>
 <span className="product-uom">/ {dv(p.unit_of_measure) || "ea"}</span>
 </div>
 <button className="ids-btn" style={{ background: "#1e40af", color: "#fff", borderColor: "#1e40af" }}
 onClick={() => navigate("product", val(p.sys_id))}>
 View Product
 </button>
 </div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ PRODUCT DETAIL ═══════════════════ */
function ProductDetail({ productId, products, addToCart, navigate }: {
 productId: string; products: Rec[];
 addToCart: (item: CartItem) => void; navigate: (v: string, id?: string) => void;
}) {
 const product = products.find(p => val(p.sys_id) === productId);
 const [qty, setQty] = useState("1");
 const [added, setAdded] = useState(false);

 if (!product) return (
 <div className="portal-section">
 <div className="ids-card"><EmptyState icon="❓" title="Product not found" desc="This product may no longer be available." /></div>
 </div>
 );

 const price = parsePrice(product.standard_cost);
 const qtyNum = parseInt(qty, 10);
 const validQty = !isNaN(qtyNum) && qtyNum > 0 && Number.isInteger(qtyNum);
 const lineTotal = validQty ? price * qtyNum : 0;
 const uom = dv(product.unit_of_measure) || "ea";

 const handleAdd = () => {
 if (!validQty) return;
 addToCart({
 productId: val(product.sys_id),
 productName: dv(product.material_name),
 quantity: qtyNum,
 uom,
 unitPrice: price,
 });
 setAdded(true);
 setTimeout(() => setAdded(false), 2000);
 };

 return (
 <div className="portal-section">
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("catalog")}>
 ← Back to Catalog
 </button>

 {/* Navy branded header */}
 <div style={{ background: "linear-gradient(135deg, #0f2438 0%, #1e3a5f 100%)", borderRadius: "10px 10px 0 0", padding: "24px 28px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <div>
 <h2 style={{ margin: "0 0 6px", fontSize: 22, fontWeight: 700, color: "#ffffff" }}>{dv(product.material_name)}</h2>
 <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
 {dv(product.material_product_id) && (
 <span style={{ fontFamily: "var(--ids-font-mono)", fontSize: 12, color: "#94a3b8", letterSpacing: "0.3px" }}>{dv(product.material_product_id)}</span>
 )}
 <span style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.5px", color: "#38bdf8" }}>{dv(product.category) || "General"}</span>
 </div>
 </div>
 </div>

 <div className="product-detail" style={{ borderRadius: "0 0 10px 10px" }}>
 {/* Left: Product Info */}
 <div>
 <div className="ids-card" style={{ borderRadius: "0 0 10px 10px", borderTop: "none", marginTop: 0 }}>
 <p style={{ fontSize: 14, color: "var(--ids-text-secondary)", lineHeight: 1.6, margin: "0 0 16px" }}>
 {dv(product.description) || "No description available for this product."}
 </p>
 {dv(product.safety_stock) && (
 <div style={{ padding: "12px 16px", background: "var(--ids-bg-surface)", borderRadius: "var(--ids-radius-sm)", fontSize: 13, color: "var(--ids-text-secondary)" }}>
 Safety Stock Level: <strong>{dv(product.safety_stock)}</strong>
 </div>
 )}
 </div>
 </div>

 {/* Right: Pricing Card */}
 <div className="pricing-card">
 <h3 style={{ margin: "0 0 16px", fontSize: 16, fontWeight: 700, color: "#0f2438" }}>Pricing</h3>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>Unit Price</span>
 <span style={{ fontSize: 16, fontWeight: 700, color: "#0f2438" }}>{price > 0 ? fmtCurrency(price) : "—"}</span>
 </div>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>UOM</span>
 <span style={{ fontSize: 14, fontWeight: 600 }}>{uom}</span>
 </div>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>Quantity</span>
 <input className="qty-input" type="number" min="1" step="1"
 value={qty} onChange={e => setQty(e.target.value)} />
 </div>
 {!validQty && qty !== "" && (
 <div style={{ fontSize: 12, color: "var(--ids-error)", marginTop: 6 }}>Enter a positive whole number.</div>
 )}
 <div className="pricing-total">
 <span>Line Total</span>
 <span>{fmtCurrency(lineTotal)}</span>
 </div>
 <button className="ids-btn" style={{ width: "100%", marginTop: 20, padding: "12px 16px", background: "#1e40af", color: "#fff", borderColor: "#1e40af" }}
 onClick={handleAdd} disabled={!validQty || price === 0}>
 {added ? "✓ Added to Cart" : "Add to Cart"}
 </button>
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ CART VIEW ═══════════════════ */
function CartView({ cart, updateQty, removeItem, navigate }: {
 cart: CartItem[]; updateQty: (i: number, q: number) => void;
 removeItem: (i: number) => void; navigate: (v: string, id?: string) => void;
}) {
 const total = cart.reduce((sum, c) => sum + c.unitPrice * c.quantity, 0);

 return (
 <div className="portal-section">
 <SectionHeader title="Shopping Cart" sub={`${cart.length} item${cart.length !== 1 ? "s" : ""} in cart`} />
 {cart.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🛒" title="Your cart is empty" desc="Browse the catalog to add products." />
 <div style={{ textAlign: "center", marginTop: 8 }}>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("catalog")}>Browse Catalog</button>
 </div>
 </div>
 ) : (
 <div className="ids-card">
 {cart.map((item, i) => (
 <div className="cart-item" key={i}>
 <div className="cart-item-info">
 <div className="cart-item-name">{item.productName}</div>
 <div className="cart-item-meta">{fmtCurrency(item.unitPrice)} / {item.uom}</div>
 </div>
 <div className="cart-controls">
 <button className="cart-qty-btn" onClick={() => updateQty(i, Math.max(1, item.quantity - 1))}>−</button>
 <div className="cart-qty-display">{item.quantity}</div>
 <button className="cart-qty-btn" onClick={() => updateQty(i, item.quantity + 1)}>+</button>
 </div>
 <div className="cart-item-price">{fmtCurrency(item.unitPrice * item.quantity)}</div>
 <button className="cart-remove" onClick={() => removeItem(i)} title="Remove">✕</button>
 </div>
 ))}
 <div className="cart-footer">
 <div className="cart-total">Total: {fmtCurrency(total)}</div>
 <div className="cart-actions">
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("catalog")}>Continue Shopping</button>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("review")}>Review Order</button>
 </div>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ ORDER REVIEW & SUBMIT ═══════════════════ */
function OrderReview({ cart, customer, clearCart, navigate }: {
 cart: CartItem[]; customer: Rec | null;
 clearCart: () => void; navigate: (v: string, id?: string) => void;
}) {
 const [deliveryDate, setDeliveryDate] = useState("");
 const [location, setLocation] = useState("");
 const [instructions, setInstructions] = useState("");
 const [submitting, setSubmitting] = useState(false);
 const [submitted, setSubmitted] = useState(false);
 const [orderNum, setOrderNum] = useState("");

 const total = cart.reduce((s, c) => s + c.unitPrice * c.quantity, 0);
 const totalQty = cart.reduce((s, c) => s + c.quantity, 0);

 const handleSubmit = async () => {
 if (!customer || !val(customer.sys_id)) return;
 setSubmitting(true);
 const custId = val(customer.sys_id);
 const orderBody: Rec = {
 customer: custId,
 status: "submitted",
 total_order_quantity: totalQty,
 };
 if (deliveryDate) orderBody.requested_delivery_date = deliveryDate;
 if (location) orderBody.delivery_location = location;
 if (instructions) orderBody.special_instructions = instructions;

 const orderRes = await apiPost(API.postOrder, orderBody);
 if (!orderRes?.result) { setSubmitting(false); return; }

 const orderId = val(orderRes.result.sys_id);
 const num = dv(orderRes.result.number);
 setOrderNum(num);

 for (const item of cart) {
 await apiPost(API.postOrderItem, {
 customer_order: orderId,
 material_product: item.productId,
 quantity_ordered: item.quantity,
 unit_of_measure: item.uom,
 });
 }

 clearCart();
 setSubmitting(false);
 setSubmitted(true);
 };

 if (submitted) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <div className="success-state">
 <div className="success-icon">✓</div>
 <div className="success-title">Order Submitted!</div>
 <div className="success-desc">
 Your order {orderNum && <strong>{orderNum}</strong>} has been submitted successfully. You can track its progress in My Orders.
 </div>
 <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("orders")}>View My Orders</button>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("catalog")}>Continue Shopping</button>
 </div>
 </div>
 </div>
 </div>
 );
 }

 if (cart.length === 0) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <EmptyState icon="📋" title="No items to review" desc="Add products to your cart first." />
 </div>
 </div>
 );
 }

 return (
 <div className="portal-section">
 <SectionHeader title="Review Order" sub="Confirm your order details before submitting" />
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("cart")}>← Back to Cart</button>

 {/* Items Summary */}
 <div className="ids-card" style={{ marginBottom: 20 }}>
 <h3 className="ids-card-title">Order Items</h3>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Product</th><th>Qty</th><th>UOM</th><th>Unit Price</th><th>Total</th></tr></thead>
 <tbody>
 {cart.map((item, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{item.productName}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{item.quantity}</td>
 <td>{item.uom}</td>
 <td>{fmtCurrency(item.unitPrice)}</td>
 <td style={{ fontWeight: 700, color: "var(--ids-brand-navy)" }}>{fmtCurrency(item.unitPrice * item.quantity)}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 <div style={{ textAlign: "right", padding: "14px 14px 0", fontSize: 18, fontWeight: 700, color: "var(--ids-brand-navy)" }}>
 Order Total: {fmtCurrency(total)} ({totalQty} items)
 </div>
 </div>

 {/* Order Form */}
 <div className="ids-card">
 <h3 className="ids-card-title">Delivery Details</h3>
 <div className="order-form">
 <div className="order-form-field">
 <label className="order-form-label">Requested Delivery Date</label>
 <input className="order-form-input" type="date" value={deliveryDate} onChange={e => setDeliveryDate(e.target.value)} />
 </div>
 <div className="order-form-field">
 <label className="order-form-label">Delivery Location</label>
 <input className="order-form-input" type="text" placeholder="e.g. Warehouse B, Dock 3" value={location} onChange={e => setLocation(e.target.value)} />
 </div>
 <div className="order-form-field full">
 <label className="order-form-label">Special Instructions</label>
 <textarea className="order-form-input" placeholder="Any special handling or delivery requirements…" value={instructions} onChange={e => setInstructions(e.target.value)} />
 </div>
 </div>
 <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 24 }}>
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("cart")}>Back to Cart</button>
 <button className="ids-btn ids-btn-accent" style={{ padding: "10px 28px" }} onClick={handleSubmit} disabled={submitting}>
 {submitting ? "Submitting…" : "Submit Order"}
 </button>
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ MY ORDERS ═══════════════════ */
function MyOrders({ orders, navigate }: { orders: Rec[]; navigate: (v: string, id?: string) => void }) {
 const [filter, setFilter] = useState("All");

 const filtered = filter === "All" ? orders : orders.filter(o => {
 const sv = dv(o.status).toLowerCase();
 const fv = filter.toLowerCase().replace(/\s+/g, "_");
 return sv === fv || val(o.status).toLowerCase() === fv || sv === filter.toLowerCase();
 });

 return (
 <div className="portal-section">
 <SectionHeader title="My Orders" sub={`${orders.length} total orders`} />
 <div className="filter-pills">
 {STATUS_FILTERS.map(f => (
 <button key={f} className={`filter-pill${filter === f ? " filter-pill-active" : ""}`} onClick={() => setFilter(f)}>
 {f}
 </button>
 ))}
 </div>
 {filtered.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="📦" title={`No ${filter.toLowerCase()} orders`} desc="Orders matching this filter will appear here." />
 </div>
 ) : (
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead>
 <tr><th>Number</th><th>Date</th><th>Delivery Date</th><th>Type</th><th>Priority</th><th>Status</th><th>Total Qty</th><th>Reference</th></tr>
 </thead>
 <tbody>
 {filtered.map((o, i) => (
 <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("order", val(o.sys_id))}>
 <td style={{ fontWeight: 600, color: "var(--ids-text-link)" }}>{dv(o.number)}</td>
 <td style={{ whiteSpace: "nowrap" }}>{fmtDate(dv(o.order_date))}</td>
 <td style={{ whiteSpace: "nowrap" }}>{dv(o.requested_delivery_date) ? fmtDate(dv(o.requested_delivery_date)) : "—"}</td>
 <td>{dv(o.order_type) || "—"}</td>
 <td>{dv(o.priority) || "—"}</td>
 <td><StatusBadge status={val(o.status)} /></td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(o.total_order_quantity) || "—"}</td>
 <td>{dv(o.customer_reference) || "—"}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ ORDER DETAIL ═══════════════════ */
function OrderDetail({ orderId, orders, orderItems, navigate }: {
 orderId: string; orders: Rec[]; orderItems: Rec[]; navigate: (v: string, id?: string) => void;
}) {
 const order = orders.find(o => val(o.sys_id) === orderId);
 if (!order) return (
 <div className="portal-section">
 <div className="ids-card"><EmptyState icon="❓" title="Order not found" /></div>
 </div>
 );

 const items = orderItems.filter(it => val(it.customer_order) === orderId);

 const fields: [string, string][] = [
 ["Number", dv(order.number)],
 ["Status", ""],
 ["Order Date", fmtDate(dv(order.order_date))],
 ["Requested Delivery", dv(order.requested_delivery_date) ? fmtDate(dv(order.requested_delivery_date)) : "—"],
 ["Order Type", dv(order.order_type) || "—"],
 ["Priority", dv(order.priority) || "—"],
 ["Total Quantity", dv(order.total_order_quantity) || "—"],
 ["Customer Reference", dv(order.customer_reference) || "—"],
 ["Delivery Location", dv(order.delivery_location) || "—"],
 ["Special Instructions", dv(order.special_instructions) || "—"],
 ];

 return (
 <div className="portal-section">
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("orders")}>← Back to Orders</button>
 <SectionHeader title={`Order ${dv(order.number)}`}>
 <StatusBadge status={val(order.status)} />
 </SectionHeader>

 <div className="ids-card" style={{ marginBottom: 20 }}>
 <h3 className="ids-card-title">Order Information</h3>
 <div className="profile-grid">
 {fields.map(([label, value], i) => (
 <div className="profile-field" key={i}>
 <div className="profile-label">{label}</div>
 {label === "Status" ? <StatusBadge status={val(order.status)} /> : <div className="profile-value">{value}</div>}
 </div>
 ))}
 </div>
 </div>

 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>Order Items ({items.length})</h3>
 </div>
 {items.length === 0 ? (
 <EmptyState icon="📋" title="No items" desc="This order has no line items." />
 ) : (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Item #</th><th>Product</th><th>Qty</th><th>UOM</th><th>Status</th><th>Priority</th></tr></thead>
 <tbody>
 {items.map((it, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{dv(it.number)}</td>
 <td>{dv(it.material_product)}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(it.quantity_ordered)}</td>
 <td>{dv(it.unit_of_measure) || "—"}</td>
 <td><StatusBadge status={val(it.item_status)} /></td>
 <td>{dv(it.priority) || "—"}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ DELIVERY ═══════════════════ */
function Delivery({ orders }: { orders: Rec[] }) {
 const activeOrders = orders.filter(o => {
 const s = val(o.status).toLowerCase();
 return s !== "completed" && s !== "cancelled" && s !== "draft";
 });

 return (
 <div className="portal-section">
 <SectionHeader title="Delivery Tracking" sub="Track delivery status of your active orders" />
 {activeOrders.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🚚" title="No active deliveries" desc="Orders in progress will appear here with delivery tracking." />
 </div>
 ) : (
 <div className="delivery-list">
 {activeOrders.map((o, i) => {
 const dd = dv(o.requested_delivery_date);
 const days = dd ? daysUntil(dd) : null;
 let countdownText = "No date set";
 let countdownClass = "";
 if (days !== null) {
 if (days < 0) { countdownText = `${Math.abs(days)} day${Math.abs(days) !== 1 ? "s" : ""} overdue`; countdownClass = "countdown-overdue"; }
 else if (days === 0) { countdownText = "Due today"; countdownClass = "countdown-soon"; }
 else if (days <= 3) { countdownText = `in ${days} day${days !== 1 ? "s" : ""}`; countdownClass = "countdown-soon"; }
 else { countdownText = `in ${days} days`; countdownClass = "countdown-ok"; }
 }
 return (
 <div className="delivery-card" key={i}>
 <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
 <div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-primary)" }}>{dv(o.number)}</div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)", marginTop: 2 }}>
 Delivery: {dd ? fmtDate(dd) : "Not scheduled"}
 </div>
 </div>
 <StatusBadge status={val(o.status)} />
 </div>
 <div className={`countdown ${countdownClass}`}>{countdownText}</div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ FEASIBILITY CHECK ═══════════════════ */
function FeasibilityCheck({ products }: { products: Rec[] }) {
 const displayProducts = products;

 const [selectedProduct, setSelectedProduct] = useState("");
 const [quantity, setQuantity] = useState("");
 const [deliveryDate, setDeliveryDate] = useState("");
 const [checking, setChecking] = useState(false);
 const [result, setResult] = useState<Rec | null>(null);
 const [error, setError] = useState("");

 const qtyNum = parseInt(quantity, 10);
 const validQty = !isNaN(qtyNum) && qtyNum > 0;
 const canCheck = selectedProduct && validQty && deliveryDate;

 const handleCheck = async () => {
 if (!canCheck) return;
 setChecking(true);
 setResult(null);
 setError("");
 try {
 const r = await fetch(FEASIBILITY_API, {
 method: "POST",
 headers: { ...hdrs(), "Content-Type": "application/json" },
 body: JSON.stringify({
 finished_product: selectedProduct,
 quantity: qtyNum,
 requested_delivery_date: deliveryDate,
 }),
 });
 const j = await r.json();
 const data = j?.result ?? j;
 if (data?.status === "ERROR") {
 setError(data.message || "Validation error.");
 } else {
 setResult(data);
 }
 } catch (e: any) {
 setError("Failed to connect to the feasibility service: " + (e.message || "Unknown error"));
 } finally {
 setChecking(false);
 }
 };

 const selectedName = displayProducts.find(p => val(p.sys_id) === selectedProduct);

 return (
 <div className="portal-section">
 <SectionHeader title="Delivery Feasibility" sub="Check whether your requested product, quantity and required delivery date can be met." />

 {/* Input Form */}
 <div className="ids-card" style={{ marginBottom: 24 }}>
 <h3 className="ids-card-title">Feasibility Parameters</h3>
 <div className="order-form">
 <div className="order-form-field">
 <label className="order-form-label">Product</label>
 <select className="order-form-input" value={selectedProduct} onChange={e => { setSelectedProduct(e.target.value); setResult(null); setError(""); }}>
 <option value="">— Select a product —</option>
 {displayProducts.map((p, i) => (
 <option key={i} value={val(p.sys_id)}>{dv(p.material_name)} ({dv(p.material_product_id)})</option>
 ))}
 </select>
 </div>
 <div className="order-form-field">
 <label className="order-form-label">Quantity</label>
 <input className="order-form-input" type="number" min="1" step="1" placeholder="e.g. 100"
 value={quantity} onChange={e => { setQuantity(e.target.value); setResult(null); setError(""); }} />
 </div>
 <div className="order-form-field">
 <label className="order-form-label">Required Delivery Date</label>
 <input className="order-form-input" type="date" value={deliveryDate}
 onChange={e => { setDeliveryDate(e.target.value); setResult(null); setError(""); }} />
 </div>
 </div>
 <div style={{ marginTop: 20 }}>
 <button className="ids-btn ids-btn-accent" style={{ padding: "10px 28px" }}
 onClick={handleCheck} disabled={!canCheck || checking}>
 {checking ? "Checking…" : "Check Feasibility"}
 </button>
 </div>
 </div>

 {/* Error State */}
 {error && (
 <div className="ids-card" style={{ borderLeft: "4px solid var(--ids-error)", marginBottom: 24 }}>
 <div style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "4px 0" }}>
 <span style={{ fontSize: 20 }}>⚠️</span>
 <div>
 <div style={{ fontSize: 14, fontWeight: 700, color: "var(--ids-error)", marginBottom: 4 }}>Validation Error</div>
 <div style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>{error}</div>
 </div>
 </div>
 </div>
 )}

 {/* Loading State */}
 {checking && <Loading msg="Evaluating feasibility across BOM, inventory, and production capacity…" />}

 {/* Result */}
 {result && !checking && (
 <>
 {/* Status Banner */}
 <div className="ids-card" style={{
 borderLeft: result.status === "FEASIBLE" ? "4px solid var(--ids-success)" : "4px solid var(--ids-error)",
 marginBottom: 24,
 }}>
 <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
 <div style={{
 width: 48, height: 48, borderRadius: "var(--ids-radius-md)",
 background: result.status === "FEASIBLE" ? "var(--ids-success-bg)" : "var(--ids-error-bg)",
 display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22,
 }}>
 {result.status === "FEASIBLE" ? "✅" : "❌"}
 </div>
 <div>
 <div style={{ fontSize: 20, fontWeight: 700, color: result.status === "FEASIBLE" ? "var(--ids-success)" : "var(--ids-error)" }}>
 {result.status === "FEASIBLE" ? "FEASIBLE" : "NOT FEASIBLE"}
 </div>
 <div style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>
 {result.product} — {result.requested_quantity} units by {result.requested_delivery_date}
 </div>
 </div>
 </div>
 </div>

 {/* NOT FEASIBLE Reasons */}
 {result.status !== "FEASIBLE" && result.reasons && result.reasons.length > 0 && (
 <div className="ids-card" style={{ marginBottom: 24 }}>
 <h3 className="ids-card-title">Reasons</h3>
 <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
 {result.reasons.map((r: string, i: number) => (
 <div key={i} style={{ display: "flex", gap: 10, fontSize: 13, color: "var(--ids-text-secondary)", lineHeight: 1.5 }}>
 <span style={{ color: "var(--ids-error)", fontWeight: 700, flexShrink: 0 }}>•</span>
 <span>{r}</span>
 </div>
 ))}
 </div>
 </div>
 )}

 {/* Summary Cards */}
 <div className="ids-grid-2" style={{ marginBottom: 24 }}>
 {/* Material Feasibility */}
 <div className="ids-card">
 <h3 className="ids-card-title">Material Feasibility</h3>
 <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
 <span style={{ fontSize: 18 }}>{result.material_feasibility?.all_materials_feasible ? "✅" : "⚠️"}</span>
 <span style={{ fontSize: 14, fontWeight: 600, color: result.material_feasibility?.all_materials_feasible ? "var(--ids-success)" : "var(--ids-warning)" }}>
 {result.material_feasibility?.all_materials_feasible ? "All materials available" : "Material shortages detected"}
 </span>
 </div>
 {result.bom && (
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)", marginBottom: 12 }}>
 BOM: {result.bom.name} ({result.bom.component_count} components)
 </div>
 )}
 {result.material_feasibility?.components && result.material_feasibility.components.length > 0 && (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Material</th><th>Required</th><th>Available</th><th>Status</th></tr></thead>
 <tbody>
 {result.material_feasibility.components.map((m: Rec, i: number) => (
 <tr key={i}>
 <td style={{ fontWeight: 600, fontSize: 12 }}>{m.material}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{m.required_quantity}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{m.available_quantity}</td>
 <td>
 <span className={m.feasible ? "ids-badge ids-badge-success" : "ids-badge ids-badge-error"}>
 {m.feasible ? "OK" : m.decision_type || "Short"}
 </span>
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 )}
 </div>

 {/* Capacity Feasibility */}
 <div className="ids-card">
 <h3 className="ids-card-title">Production Capacity</h3>
 <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
 <span style={{ fontSize: 18 }}>{result.capacity_feasibility?.feasible ? "✅" : "⚠️"}</span>
 <span style={{ fontSize: 14, fontWeight: 600, color: result.capacity_feasibility?.feasible ? "var(--ids-success)" : "var(--ids-warning)" }}>
 {result.capacity_feasibility?.feasible ? "Capacity available" : "Capacity constrained"}
 </span>
 </div>
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {result.capacity_feasibility?.resource && (
 <div className="profile-field">
 <div className="profile-label">Resource</div>
 <div className="profile-value">{result.capacity_feasibility.resource}</div>
 </div>
 )}
 {result.capacity_feasibility?.effective_capacity_per_day > 0 && (
 <div className="profile-field">
 <div className="profile-label">Effective Capacity</div>
 <div className="profile-value">{result.capacity_feasibility.effective_capacity_per_day.toFixed(1)} units/day</div>
 </div>
 )}
 {result.capacity_feasibility?.days_needed > 0 && (
 <div className="profile-field">
 <div className="profile-label">Production Days Needed</div>
 <div className="profile-value">{result.capacity_feasibility.days_needed} days</div>
 </div>
 )}
 {result.earliest_completion_date && (
 <div className="profile-field">
 <div className="profile-label">Earliest Completion</div>
 <div className="profile-value" style={{ fontWeight: 700, color: result.capacity_feasibility?.feasible ? "var(--ids-success)" : "var(--ids-error)" }}>
 {result.earliest_completion_date}
 </div>
 </div>
 )}
 {result.capacity_feasibility?.existing_schedule_conflicts > 0 && (
 <div className="profile-field">
 <div className="profile-label">Existing Schedules</div>
 <div className="profile-value">{result.capacity_feasibility.existing_schedule_conflicts} active</div>
 </div>
 )}
 </div>
 </div>
 </div>

 {/* Request Summary (FEASIBLE only) */}
 {result.status === "FEASIBLE" && (
 <div className="ids-card">
 <h3 className="ids-card-title">Feasibility Summary</h3>
 <div className="profile-grid">
 <div className="profile-field">
 <div className="profile-label">Product</div>
 <div className="profile-value">{result.product} ({result.product_id})</div>
 </div>
 <div className="profile-field">
 <div className="profile-label">Requested Quantity</div>
 <div className="profile-value">{result.requested_quantity}</div>
 </div>
 <div className="profile-field">
 <div className="profile-label">Requested Delivery Date</div>
 <div className="profile-value">{result.requested_delivery_date}</div>
 </div>
 <div className="profile-field">
 <div className="profile-label">Expected Completion</div>
 <div className="profile-value" style={{ fontWeight: 700, color: "var(--ids-success)" }}>{result.earliest_completion_date}</div>
 </div>
 </div>
 </div>
 )}
 </>
 )}
 </div>
 );
}

/* ═══════════════════ SURVEYS ═══════════════════ */
function Surveys() {
 const [rating, setRating] = useState(0);
 const [comment, setComment] = useState("");
 const [submitting, setSubmitting] = useState(false);
 const [submitted, setSubmitted] = useState(false);
 const [configuring, setConfiguring] = useState(false);

 const handleSubmit = async () => {
 if (rating === 0) return;
 setSubmitting(true);
 const res = await apiPost(`/api/now/table/${SCOPE}_cust_survey`, {
 rating: rating.toString(),
 comments: comment,
 });
 setSubmitting(false);
 if (res?.result) {
 setSubmitted(true);
 } else {
 setConfiguring(true);
 }
 };

 if (submitted) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <div className="success-state">
 <div className="success-icon">✓</div>
 <div className="success-title">Thank You!</div>
 <div className="success-desc">Your feedback has been submitted. We appreciate you taking the time to help us improve.</div>
 </div>
 </div>
 </div>
 );
 }

 if (configuring) {
 return (
 <div className="portal-section">
 <SectionHeader title="Customer Survey" sub="Share your feedback" />
 <div className="ids-card">
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "40px 24px", textAlign: "center", gap: 12 }}>
 <div style={{ width: 56, height: 56, borderRadius: "var(--ids-radius-lg)", background: "var(--ids-info-bg)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 24 }}>🔧</div>
 <div style={{ fontSize: 17, fontWeight: 700 }}>Survey Submission Being Configured</div>
 <div style={{ fontSize: 14, color: "var(--ids-text-secondary)", maxWidth: 440, lineHeight: 1.5 }}>
 The survey submission system is currently being set up. Your feedback is important to us — please check back soon.
 </div>
 </div>
 </div>
 </div>
 );
 }

 return (
 <div className="portal-section">
 <SectionHeader title="Customer Survey" sub="We'd love to hear your feedback" />
 <div className="ids-card" style={{ maxWidth: 600 }}>
 <h3 className="ids-card-title">How would you rate your experience?</h3>
 <div className="rating-stars">
 {[1, 2, 3, 4, 5].map(n => (
 <button key={n} className={`star-btn${rating >= n ? " star-btn-filled" : ""}`} onClick={() => setRating(n)}>
 ★
 </button>
 ))}
 {rating > 0 && <span style={{ fontSize: 13, color: "var(--ids-text-secondary)", marginLeft: 8, alignSelf: "center" }}>{rating} / 5</span>}
 </div>
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "var(--ids-text-secondary)", marginBottom: 6 }}>Comments (optional)</label>
 <textarea className="order-form-input" style={{ width: "100%" }}
 placeholder="Share your thoughts, suggestions, or concerns…"
 value={comment} onChange={e => setComment(e.target.value)} />
 </div>
 <button className="ids-btn ids-btn-accent" onClick={handleSubmit} disabled={rating === 0 || submitting}>
 {submitting ? "Submitting…" : "Submit Feedback"}
 </button>
 </div>
 </div>
 );
}

/* ═══════════════════ PROFILE ═══════════════════ */
function Profile({ customer }: { customer: Rec | null }) {
 if (!customer) {
 return (
 <div className="portal-section">
 <SectionHeader title="My Profile" />
 <div className="ids-card">
 <EmptyState icon="👤" title="No customer profile found" desc="Your customer record could not be loaded. Please contact support." />
 </div>
 </div>
 );
 }

 const fields: [string, string][] = [
 ["Customer Name", dv(customer.customer_name)],
 ["Customer ID", dv(customer.customer_id)],
 ["Contact Email", dv(customer.contact_email)],
 ["Phone", dv(customer.contact_phone)],
 ["Billing Address", dv(customer.billing_address)],
 ["Shipping Address", dv(customer.shipping_address)],
 ["Payment Terms", dv(customer.payment_terms)],
 ["Credit Limit", dv(customer.credit_limit)],
 ["City", dv(customer.city)],
 ["State", dv(customer.state)],
 ["Country", dv(customer.country)],
 ];

 return (
 <div className="portal-section">
 <SectionHeader title="My Profile" sub="Your customer account information" />
 <div className="ids-card">
 <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 24, paddingBottom: 20, borderBottom: "1px solid var(--ids-border)" }}>
 <div style={{ width: 52, height: 52, borderRadius: "50%", background: "var(--ids-brand-navy)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, fontWeight: 700 }}>
 {(dv(customer.customer_name) || "C").charAt(0).toUpperCase()}
 </div>
 <div>
 <div style={{ fontSize: 18, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{dv(customer.customer_name)}</div>
 <div style={{ fontSize: 13, color: "var(--ids-text-tertiary)" }}>{dv(customer.customer_id)}</div>
 </div>
 </div>
 <div className="profile-grid">
 {fields.map(([label, value], i) => (
 <div className="profile-field" key={i}>
 <div className="profile-label">{label}</div>
 <div className="profile-value">{value || "—"}</div>
 </div>
 ))}
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ APP ROOT ═══════════════════ */
function App() {
 const [route, setRoute] = useState<Route>(parseHash);
 const [ctx, setCtx] = useState<CustCtx | null>(null);
 const [orders, setOrders] = useState<Rec[]>([]);
 const [orderItems, setOrderItems] = useState<Rec[]>([]);
 const [products, setProducts] = useState<Rec[]>([]);
 const [cart, setCart] = useState<CartItem[]>([]);
 const [loading, setLoading] = useState(true);

 /* ── Hash listener ── */
 useEffect(() => {
 const onHash = () => setRoute(parseHash());
 window.addEventListener("hashchange", onHash);
 return () => window.removeEventListener("hashchange", onHash);
 }, []);

 /* ── Load data: 2-phase (context first, then customer-scoped) ── */
 useEffect(() => {
 let m = true;
 (async () => {
 const [c, p] = await Promise.all([
 apiFetch<CustCtx>(API.context),
 apiFetch<Rec[]>(API.products),
 ]);
 if (!m) return;
 setProducts(Array.isArray(p) ? p : []);
 const resolved: CustCtx = c && typeof c.linked === "boolean" ? c : { linked: false, message: "Unable to resolve customer identity." };
 setCtx(resolved);
 if (resolved.linked && resolved.customer) {
 const cid = resolved.customer.sys_id;
 const [o, oi] = await Promise.all([
 apiFetch<Rec[]>(buildOrdersUrl(cid)),
 apiFetch<Rec[]>(buildItemsUrl(cid)),
 ]);
 if (!m) return;
 setOrders(Array.isArray(o) ? o : []);
 setOrderItems(Array.isArray(oi) ? oi : []);
 }
 setLoading(false);
 })();
 return () => { m = false; };
 }, []);

 /* ── Navigate ── */
 const navigate = useCallback((view: string, id?: string) => { setHash(view, id); }, []);

 /* ── Cart ops ── */
 const addToCart = useCallback((item: CartItem) => {
 setCart(prev => {
 const idx = prev.findIndex(c => c.productId === item.productId);
 if (idx >= 0) {
 const upd = [...prev];
 upd[idx] = { ...upd[idx], quantity: upd[idx].quantity + item.quantity };
 return upd;
 }
 return [...prev, item];
 });
 }, []);
 const updateQty = useCallback((i: number, q: number) => {
 setCart(prev => { const u = [...prev]; u[i] = { ...u[i], quantity: q }; return u; });
 }, []);
 const removeItem = useCallback((i: number) => {
 setCart(prev => prev.filter((_, idx) => idx !== i));
 }, []);
 const clearCart = useCallback(() => setCart([]), []);

 /* ── Derive active tab ── */
 const activeTab = route.view === "product" || route.view === "review" ? (route.view === "review" ? "cart" : "catalog")
 : route.view === "order" ? "orders"
 : route.view === "cart" ? "cart"
 : NAV_TABS.find(t => t.key === route.view) ? route.view : "dashboard";

 const isLinked = ctx?.linked === true;
 const customer: Rec | null = isLinked && ctx?.customer ? ctx.customer : null;
 const customerName = customer ? (customer.customer_name || "") : "";

 return (
 <div className="portal-shell">
 {/* ── Header ── */}
 <header className="portal-header">
 <div className="portal-header-top">
 <div className="portal-brand">
 <div className="portal-brand-icon">🏭</div>
 Industrial Supply Co.
 </div>
 <div className="portal-header-right">
 {customerName && <span className="portal-customer-name">Welcome, {customerName}</span>}
 <button className="portal-cart-btn" onClick={() => navigate("cart")}>
 🛒 Cart
 {cart.length > 0 && <span className="portal-cart-badge">{cart.reduce((s, c) => s + c.quantity, 0)}</span>}
 </button>
 </div>
 </div>
 <nav className="portal-nav">
 {NAV_TABS.map(t => (
 <button key={t.key}
 className={`portal-tab${activeTab === t.key ? " portal-tab-active" : ""}`}
 onClick={() => navigate(t.key)}>
 {t.label}
 </button>
 ))}
 </nav>
 </header>

 {/* ── Main Content ── */}
 <main className="portal-content">
 {loading ? <Loading msg="Loading portal…" /> : (
 <>
 {route.view === "dashboard" && (isLinked ? <Dashboard orders={orders} orderItems={orderItems} products={products} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "catalog" && <Catalog products={products} navigate={navigate} />}
 {route.view === "product" && route.id && <ProductDetail productId={route.id} products={products} addToCart={addToCart} navigate={navigate} />}
 {route.view === "cart" && <CartView cart={cart} updateQty={updateQty} removeItem={removeItem} navigate={navigate} />}
 {route.view === "review" && (isLinked ? <OrderReview cart={cart} customer={customer} clearCart={clearCart} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "orders" && (isLinked ? <MyOrders orders={orders} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "order" && route.id && (isLinked ? <OrderDetail orderId={route.id} orders={orders} orderItems={orderItems} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "delivery" && (isLinked ? <Delivery orders={orders} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "feasibility" && <FeasibilityCheck products={products} />}
 {route.view === "surveys" && <Surveys />}
 {route.view === "profile" && (isLinked ? <Profile customer={customer} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 </>
 )}
 </main>
 </div>
 );
}

/* ═══════════════════ MOUNT ═══════════════════ */
const rootEl = document.getElementById("root");
if (rootEl) ReactDOM.createRoot(rootEl).render(<App />);
